export const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function inline(s){return escapeHtml(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
export function blocks(source){const result=[];const lines=source.replace(/\r/g,'').trim().split('\n');for(let i=0;i<lines.length;i++){const l=lines[i];if(!l.trim())continue;if(l.startsWith('```')){const code=[];while(++i<lines.length&&!lines[i].startsWith('```'))code.push(lines[i]);result.push({type:'code',text:code.join('\n')});}else if(l.startsWith('|')){const rows=[];do{if(!/^\|[-:\s|]+\|$/.test(lines[i]))rows.push(lines[i].split('|').slice(1,-1).map(s=>s.trim()));i++;}while(i<lines.length&&lines[i].startsWith('|'));i--;result.push({type:'table',headers:rows[0],rows:rows.slice(1)});}else{const p=[l];while(i+1<lines.length&&lines[i+1].trim()&&!/^(\||```)/.test(lines[i+1]))p.push(lines[++i]);result.push({type:'text',text:p.join('\n')});}}return result;}
export function renderBlock(b){if(b.type==='code')return '<pre>'+escapeHtml(b.text)+'</pre>';if(b.type==='text')return '<p>'+inline(b.text).replace(/\n/g,'<br>')+'</p>';return '<table><thead><tr>'+b.headers.map(x=>'<th>'+inline(x)+'</th>').join('')+'</tr></thead><tbody>'+b.rows.map(row=>'<tr>'+row.map(x=>'<td>'+inline(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
